const input = $input.first().json || {};

function normalize(value) {
  return value === undefined || value === null
    ? ""
    : String(value).trim().toLowerCase();
}

function normalizePhone(value) {
  return normalize(value).replace(/[^0-9]/g, "");
}

function emailDomain(value) {
  const email = normalize(value);
  if (!email.includes("@")) return "";
  return email.split("@")[1];
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-P",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        suppression: {
          status: "failed",
          decision: null,
          allowed_to_contact: null,
          recommended_action: null,
          reasons: [],
          matched_records: [],
          checked_records: 0
        },
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const payload = source.payload || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-P will not run suppression check when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "suppression_check") {
  return fail({
    code: "SUPPRESSION_NOT_REQUESTED",
    message: "source.next_action is not suppression_check.",
    details: [{ next_action: source.next_action || null }]
  });
}

const incoming = {
  email: normalize(payload.email),
  phone: normalizePhone(payload.phone),
  domain: emailDomain(payload.email),
  consent_status: normalize(payload.consent_status)
};

const suppressionRecords = Array.isArray(config.suppression_records)
  ? config.suppression_records
  : [];

const blockedEmails = (config.blocked_emails || []).map(normalize);
const blockedPhones = (config.blocked_phones || []).map(normalizePhone);
const blockedDomains = (config.blocked_domains || []).map(normalize);

const allowedConsentValues = (config.allowed_consent_values || []).map(normalize);
const manualReviewConsentValues = (config.manual_review_consent_values || []).map(normalize);

const reasons = [];
const matchedRecords = [];

if (incoming.email && blockedEmails.includes(incoming.email)) {
  reasons.push("blocked_email_match");
}

if (incoming.phone && blockedPhones.includes(incoming.phone)) {
  reasons.push("blocked_phone_match");
}

if (incoming.domain && blockedDomains.includes(incoming.domain)) {
  reasons.push("blocked_domain_match");
}

for (const record of suppressionRecords) {
  const recordEmail = normalize(record.email);
  const recordPhone = normalizePhone(record.phone);
  const recordDomain = emailDomain(record.email);
  const recordStatus = normalize(record.status || "active");

  if (recordStatus && recordStatus !== "active") {
    continue;
  }

  const recordReasons = [];

  if (incoming.email && recordEmail && incoming.email === recordEmail) {
    recordReasons.push("suppression_email_match");
  }

  if (incoming.phone && recordPhone && incoming.phone === recordPhone) {
    recordReasons.push("suppression_phone_match");
  }

  if (incoming.domain && recordDomain && incoming.domain === recordDomain) {
    recordReasons.push("suppression_domain_match");
  }

  if (recordReasons.length > 0) {
    reasons.push(...recordReasons);
    matchedRecords.push({
      record_id: record.record_id || null,
      reason: record.reason || null,
      source: record.source || null,
      status: record.status || null,
      match_reasons: recordReasons
    });
  }
}

let decision = "allowed";
let allowedToContact = true;
let recommendedAction = config.default_next_action || "write_record";
let status = "clear";

if (reasons.length > 0) {
  decision = "blocked";
  allowedToContact = false;
  recommendedAction = "do_not_contact";
  status = "blocked";
} else if (config.require_consent === true) {
  if (!incoming.consent_status) {
    decision = "manual_review";
    allowedToContact = false;
    recommendedAction = "manual_review";
    status = "consent_review_required";
    reasons.push("missing_consent_status");
  } else if (manualReviewConsentValues.includes(incoming.consent_status)) {
    decision = "manual_review";
    allowedToContact = false;
    recommendedAction = "manual_review";
    status = "consent_review_required";
    reasons.push("uncertain_consent_status");
  } else if (!allowedConsentValues.includes(incoming.consent_status)) {
    decision = "blocked";
    allowedToContact = false;
    recommendedAction = "do_not_contact";
    status = "blocked";
    reasons.push("consent_not_allowed");
  }
}

return [
  {
    json: {
      success: true,
      component_id: "C2-P",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      suppression: {
        status,
        decision,
        allowed_to_contact: allowedToContact,
        recommended_action: recommendedAction,
        reasons: [...new Set(reasons)],
        matched_records: matchedRecords,
        checked_records: suppressionRecords.length,
        consent_status: incoming.consent_status || null
      },
      source_result: source,
      error: null,
      next_action: recommendedAction
    }
  }
];
